/bin/zsh -lc "python3 -B -c 'import csv, json
from collections import defaultdict
from pathlib import Path
p = Path.cwd()
with (p/'\\''data/ModelCondition.csv'\\'').open() as f: rows = list(csv.DictReader(f))
with (p/'\\''data/ScreenSequenceMap.csv'\\'').open() as f: seq = list(csv.DictReader(f))
def kval(r):
    fmt = (r.get('\\''CellFormat'\\'') or '\\'''\\'').strip()
    form = (r.get('\\''FormulationID'\\'') or '\\'''\\'').strip()
    return None if fmt.lower() in ('\\'''\\'','\\''unknown'\\'') or not form else (fmt,form)
groups=defaultdict(set)
for r in rows:
    k=kval(r)
    if k is not None: groups[(k[0].lower(),k[1])].add(k)
eligible=[r for r in seq if r['\\''ModelID'\\''] "'!= '"'\\''pDNA'\\'' and r['\\''ScreenType'\\''] "'!= '"'\\''pDNA'\\'' and r['\\''PassesQC'\\''].strip().lower() == '\\''true'\\'' and all(r[k].strip().lower() == '\\''false'\\'' for k in ['\\''DrugTreated'\\'','\\''IsEngineered'\\'','\\''ExcludeFromCRISPRCombined'\\'']) and r['\\''Library'\\''].strip()]
byid={r['\\''ModelConditionID'\\'']:r for r in rows}
nodes={r['\\''ModelConditionID'\\''] for r in eligible}
dangling=[r for r in rows if r['\\''ParentModelConditionID'\\''].strip() and r['\\''ParentModelConditionID'\\''].strip() not in byid]
print(json.dumps({'\\''unqualified_independent'\\'':sum(kval(r) is None for r in rows),'\\''case_normalization_collision_groups'\\'':sum(len(v)>1 for v in groups.values()),'\\''strict_sequences'\\'':len(eligible),'\\''strict_screens'\\'':len({r['\\''ScreenID'\\''] for r in eligible}),'\\''strict_condition_nodes'\\'':len(nodes),'\\''strict_qualified_condition_nodes'\\'':sum(kval(byid[n]) is not None for n in nodes),'\\''strict_dangling_nodes'\\'':sorted(nodes & {r['\\''ModelConditionID'\\''] for r in dangling})},indent=2))
'"

